# -*- coding: utf-8 -*-
"""Lecture 49 vignette pool B -- Hematologic Malignancies Part I: acute myeloid leukemia (s31-42), acute
promyelocytic leukemia (s43), myelodysplastic syndrome (s45-49). Every slide in the range viewed at 1920 px
(s32 subtype table, s33 subtype picture, s36 Auer rod picture, s45 dysplasia picture).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md.

Laboratory ranges in the stems are standard adult reference ranges and only set the scene. Blast percentages in
stems never sit on a boundary and never fall between 5 and 19% (s38: certain mutations allow an acute myeloid
leukemia diagnosis at 10% or more, so a 10-19% stem has two defensible readings).

Deliberately NOT keyed: "most common leukemia" (s31 vs Lecture 50); subtype numbers from the s32 table; any
regimen schedule ("7+3" is not used as a regimen name in the questions); the favorable-risk five-year figure.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e8l49_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


